--
-- Table structure for table `assets`
--

DROP TABLE IF EXISTS `assets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `assets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `asset_code` varchar(100) NOT NULL,
  `asset_serial` varchar(255) DEFAULT NULL,
  `rfid_tag` varchar(255) DEFAULT NULL,
  `tag_type_id` int DEFAULT NULL,
  `vendor_id` int DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `asset_type_id` int DEFAULT NULL,
  `current_location_id` int DEFAULT NULL,
  `status` enum('active','inactive','maintenance') DEFAULT 'active',
  `description` text,
  `asset_inventory_status` enum('in_inventory','missing','not_in_inventory') NOT NULL DEFAULT 'in_inventory' COMMENT 'in_inventory=expected on books; missing=not located in scan; not_in_inventory=excluded from cycle count',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `image_url` varchar(500) DEFAULT NULL,
  `is_custom_image` tinyint(1) NOT NULL DEFAULT '0',
  `attachment_url` varchar(500) DEFAULT NULL,
  `attachment_name` varchar(255) DEFAULT NULL,
  `rfid_last_seen_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_assets_asset_code` (`asset_code`),
  UNIQUE KEY `rfid_tag` (`rfid_tag`),
  UNIQUE KEY `asset_serial` (`asset_serial`),
  KEY `asset_type_id` (`asset_type_id`),
  KEY `current_location_id` (`current_location_id`),
  KEY `fk_assets_tag_type` (`tag_type_id`),
  KEY `fk_assets_vendor` (`vendor_id`),
  CONSTRAINT `assets_ibfk_2` FOREIGN KEY (`current_location_id`) REFERENCES `locations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_assets_tag_type` FOREIGN KEY (`tag_type_id`) REFERENCES `tag_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_assets_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3488 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

